-- Exam guide corrections checked against the official documents on 25 November 2026. Only the content keys named here are
-- replaced (jsonb ||), so dates, notices and every other field stay as the daily notification sync and editors left them.
--
-- AISSEE: the AISSEE-2027 information bulletin (NTA, 3 Nov 2026) replaces the AISSEE-2026 age windows and fee; the FAQ no
-- longer says the 2027 dates are unannounced (NTA's notice of 3 Nov 2026 opened applications until 2 Dec 2026); exam-day
-- timings are added. JNVST: the result, answer-key, wait-list and document rules of the JNVST-2027 prospectus (2.3, 3.1-3.8).
-- The same text is in seed/exams.json; ExamSeedMigrationTest keeps the two equal.

UPDATE exam
SET content = content || '{"eligibility":["Class VI (AISSEE-2027, admission 2027-28): 10–12 years as on 31.03.2027 — born 01.04.2015 to 31.03.2017 (both days inclusive).","Class IX (AISSEE-2027, admission 2027-28): 13–15 years as on 31.03.2027 — born 01.04.2012 to 31.03.2014, and passed Class VIII from a recognised school at the time of admission.","Girls can apply for Class VI, and for Class IX where vacancies exist, with the same age limits as boys (for approved New Sainik Schools, check the school’s own admission policy).","Home State vs Outside State is decided by the candidate’s domicile and the location of the Sainik School chosen.","Age windows move forward by one year each cycle; these are the AISSEE-2027 windows."],"selection":["Qualifying standard (AISSEE-2027 bulletin): at least 25% marks in each subject and 40% in aggregate. Existing Sainik Schools prescribe no minimum for SC/ST candidates; approved New Sainik Schools apply the rule to everyone.","School-wise, gender-wise and category-wise (Home State / Outside State) merit lists, followed by e-counselling.","Medical fitness and original-document verification at the allotted school.","Approved New Sainik Schools fill at least 40% of seats from AISSEE merit (Category A)."],"fee":"AISSEE-2027 application fee: ₹850 (General / Defence / OBC-NCL), ₹700 (SC/ST), not refundable; late applications (3–6 Dec 2026) pay a ₹500 late fee. School fees differ by Sainik School — see each school’s fee structure.","faq":[{"question":"Have the AISSEE-2027 dates been announced?","answer":"Yes. NTA’s public notice of 3 November 2026 opened applications until 2 December 2026 (11:50 p.m.), with late applications and a ₹500 late fee from 3 to 6 December. The exam is on 31 January 2027 and admit cards are due on 25 January 2027.","guidance":false},{"question":"What is the age limit for Class 6 in AISSEE-2027?","answer":"10 to 12 years on 31 March 2027: the child must be born between 1 April 2015 and 31 March 2017 (both days inclusive). For Class 9 it is 13 to 15 years: born between 1 April 2012 and 31 March 2014.","guidance":false},{"question":"Can girls apply to Sainik Schools?","answer":"Yes. Admission for girls is open in Class VI, and in Class IX where vacancies exist, with the same age limits as boys. For approved New Sainik Schools, check the school’s own admission policy.","guidance":false},{"question":"Is there negative marking?","answer":"No. The AISSEE-2027 bulletin says there is no negative marking for a wrong response, so it is worth attempting every question.","guidance":true},{"question":"What marks are needed to qualify?","answer":"At least 25% in each subject and 40% in aggregate. Existing Sainik Schools prescribe no minimum for SC/ST candidates; approved New Sainik Schools apply the rule to everyone. Admission then follows e-counselling on the merit list, a medical check and document verification.","guidance":false},{"question":"Will NTA publish an answer key?","answer":"The AISSEE-2027 bulletin says the attempted question papers and provisional answer keys will be displayed on the NTA AISSEE website on a date to be announced. NTA’s final answer keys for earlier years are linked under Official papers.","guidance":false}],"officialLinks":[{"label":"NTA AISSEE page","url":"https://exams.nta.nic.in/sainik-school-society/"},{"label":"AISSEE-2027 public notice (PDF)","url":"https://nta.ac.in/Download/Notice/Notice_20261103151121.PDF"},{"label":"AISSEE-2027 information bulletin (PDF)","url":"https://cdnbbsr.s3waas.gov.in/s388a839f2f6f1427879fc33ee4acf4f66/uploads/2026/11/202611031403322790.pdf"},{"label":"National Testing Agency","url":"https://nta.ac.in/"}],"sources":[{"label":"AISSEE-2027 information bulletin (PDF)","url":"https://cdnbbsr.s3waas.gov.in/s388a839f2f6f1427879fc33ee4acf4f66/uploads/2026/11/202611031403322790.pdf"},{"label":"NTA public notice, 3 Nov 2026 (AISSEE-2027 schedule)","url":"https://nta.ac.in/Download/Notice/Notice_20261103151121.PDF"},{"label":"AISSEE-2026 information bulletin (PDF)","url":"https://cdnbbsr.s3waas.gov.in/s388a839f2f6f1427879fc33ee4acf4f66/uploads/2025/10/20251010937989896.pdf"},{"label":"NTA AISSEE page","url":"https://exams.nta.nic.in/sainik-school-society/"},{"label":"nta.ac.in","url":"https://nta.ac.in/Download/Notice/Notice_20251010181643.pdf"},{"label":"nta.ac.in","url":"https://nta.ac.in/Download/Notice/Notice_20251030154635.pdf"},{"label":"nta.ac.in","url":"https://nta.ac.in/Download/Notice/Notice_20260227175656.pdf"},{"label":"nta.ac.in","url":"https://nta.ac.in/Download/Notice/Notice_20260211210548.pdf"},{"label":"nta.ac.in","url":"https://nta.ac.in/Download/Notice/Notice_20260112162229.pdf"},{"label":"nta.ac.in","url":"https://nta.ac.in/Download/Notice/Notice_20260106211946.pdf"},{"label":"nta.ac.in","url":"https://nta.ac.in/Download/Notice/Notice_20251025180445.pdf"}],"examDay":["Class VI: 2:00 p.m. to 4:30 p.m. (150 minutes). Class IX: 2:00 p.m. to 5:00 p.m. (180 minutes).","Pen and paper: answers are marked on an OMR sheet, at the centre named on the admit card."]}'::jsonb,
    last_verified_on = DATE '2026-11-25',
    updated_at = now()
WHERE slug = 'aissee';

UPDATE exam
SET content = content || '{"selection":["Merit in the selection test, district-wise. At least 75% of seats for rural candidates; the rest are open.","At least one-third of seats for girls; SC/ST as per district population (minimum 15% SC and 7.5% ST); 27% OBC (Central list); Divyang reservation as per GOI norms.","Ties broken by Mental Ability & EVS marks, then Arithmetic, then category and age rules in the prospectus.","Provisional selection is confirmed only after document verification at the JNV.","No wait-lists: if a selected candidate does not join or lacks the required certificates, the next candidate in the same category and quota is moved up through the admission portal. Admissions close by 31 August 2027."],"faq":[{"question":"Is there an application fee for JNVST?","answer":"No. The prospectus states that registration for the selection test is free.","guidance":false},{"question":"Can a child appear in JNVST more than once?","answer":"No. A candidate can appear only once; repeaters are disqualified.","guidance":false},{"question":"Which district should we apply in?","answer":"The district where the child is a bona fide resident and studying in Class V, as defined in the prospectus.","guidance":false},{"question":"When will the JNVST 2027 result be announced?","answer":"The prospectus says the result is expected by the end of March 2027. It is published on the NVS admission portal and navodaya.gov.in, and displayed at the JNV, the offices of the District Education Officer and the District Magistrate, and the NVS regional office. The JNV principal also informs selected candidates by speed post.","guidance":false},{"question":"Does NVS publish an answer key for JNVST?","answer":"The JNVST-2027 prospectus does not provide for an answer key, and we found no official key for earlier years; keys shared on other websites are unofficial. Marks are calculated electronically, and the prospectus rules out re-evaluation, re-totalling and scrutiny.","guidance":false},{"question":"Is there a waiting list or second list?","answer":"No. NVS does not release wait-lists. If a provisionally selected candidate does not join or cannot produce the required certificates, the next candidate in the same category and quota is moved up through the admission portal. Admissions close by 31 August 2027.","guidance":false},{"question":"Which documents are checked after selection?","answer":"The originals the prospectus asks for, including a birth certificate issued by a government authority before registration, proof of residence in the district, a Central-list OBC, SC or ST certificate when claiming that category, a rural-area certificate if the Class III–V school’s location is not on UDISE, and a UDID or CMO certificate for Divyang candidates. Parents are also advised to get a transfer certificate from the current school. Selection stays provisional until the JNV verifies them.","guidance":false}]}'::jsonb,
    last_verified_on = DATE '2026-11-25',
    updated_at = now()
WHERE slug = 'jnvst';
